const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function choose(t){
 const resume=adcRequestStarted&&t===selected;
 adcRequestStarted=true;
 if(!resume){
 if(selected==='Duelo'&&t!=='Duelo'&&adcDueloAutoUntil&&$('hasta').value===adcDueloAutoUntil)$('hasta').value='';
 if(t!=='Duelo')adcDueloAutoUntil='';
 selected=t;
 $('adcDueloFields').hidden=t!=='Duelo';
 if(t==='Duelo'){
  $('pago').value='con';
  $('adcDueloRelations').replaceChildren(...adcDueloRelations.flatMap(([name,,aliases=''])=>[name,...aliases.split(' ').filter(Boolean)].map(value=>new Option(name,value))));
  adcDueloSuggest();
 }
 $('justifica').value=classify()==='inasistencia'?'si':'';
 }
 adcRequestFields();
 usage[t]=(usage[t]||0)+1;localStorage.setItem('adc_v07_usage',JSON.stringify(usage));$('elegido').innerHTML='<b>Seleccionado: '+esc(adcTramiteLabel(t))+'</b>'+(!adcDL01Ready.has(t)?adcPendingFormMarkup():'')+'<div id="adcDurationLegend" class="small" aria-live="polite"></div><div class="small">El encuadre se propone solo cuando existe una referencia registrada; los demás quedan pendientes de verificación.</div>';adcChoosePendingForm();renderFrecuentes();review()}

let adcRequestStarted=false;
function adcRequestFields(){
 const applies=classify()==='inasistencia';
 const field=$('adcJustificaField');
 field.hidden=!applies;
 field.style.display=applies?'':'none';
 const fixed=selected==='Enfermedad o lesión común';
 $('pago').disabled=fixed;
 if(fixed)$('pago').value='con';
}

function adcPendingFormMarkup(){
 return `<fieldset id="adcPendingForms">
  <legend>¿Sabés qué formulario necesitás?</legend>
  <p class="small">Si tu institución te indicó qué formulario usar, elegilo acá.</p>
  <label><input type="radio" name="adcPendingForm" value="dl01"> DL-01 · Licencias y permisos</label>
  <label><input type="radio" name="adcPendingForm" value="dj02"> DJ-02 · Licencias anteriores</label>
  <label><input type="radio" name="adcPendingForm" value="ol01"> OL-01 · Solicitud de licencia</label>
  <p id="adcPendingPrintHint" class="small" role="status"></p>
  <div id="adcPendingFormPreview"></div>
 </fieldset>`;
}
function adcChoosePendingForm(){
 const pending=Boolean(selected)&&!adcDL01Ready.has(selected);
 $('adcConfiguredDL01').hidden=pending;
 $('pdfResult').hidden=pending;
 $('adcDJ02FromSelector').hidden=true;
 $('adcDJ02PrintButton').disabled=false;
}
document.getElementById('elegido').addEventListener('change',event=>{
 if(event.target.name!=='adcPendingForm')return;
 const choice=event.target.value;
 $('adcPendingPrintHint').textContent='Imprimí un formulario a la vez.';
 const preview=$('adcPendingFormPreview');
 preview.replaceChildren();
 if(choice==='dl01'){
  $('adcDJ02FromSelector').hidden=true;
  preview.innerHTML=`<p class="small" role="status">Vista de la plantilla DL-01. Falta verificar e incorporar el encuadre, el código y el artículo aplicables antes de completar e imprimir este formulario.</p>
   <img alt="Plantilla en blanco del DL-01" src="data:image/png;base64,">
   <button type="button" disabled>Imprimir DL-01</button>`;
 }
 if(choice==='ol01')adcOLStart(true);
 if(choice==='dj02'){
  $('adcDJ02FromSelector').hidden=false;
  tab('dj02');
  $('adcDJ02FromSelector').scrollIntoView({block:'nearest'});
 }
});
function adcCheckDJ02Print(){
 const contextual=!$('adcDJ02FromSelector').hidden;
 const issues=[];
 if(contextual){
  if(dj02Fields.some(key=>!dj02Val(key).trim())||!adcPersonalValid(dj02Val('Dni'),7,8)||!adcPersonalValid(dj02Val('Clase'),4))
   issues.push('Completá los datos de la declaración, el DNI y la institución de presentación.');
  if(dj02Records.some(row=>!row.motivo?.trim()||!row.articulo?.trim()||!row.unidad?.trim()||
    !date(row.desde)||!date(row.hasta)||row.hasta<row.desde))
   issues.push('Revisá el motivo, el artículo, la institución y las fechas de cada antecedente.');
  if(dj02Records.length>14)issues.push('La plantilla admite hasta 14 antecedentes.');
 }
 $('adcDJ02PrintStatus').textContent=issues.join(' ');
 $('adcDJ02PrintButton').disabled=issues.length>0;
 return !issues.length;
}

function renderFrecuentes(){let used=Object.keys(usage).sort((a,b)=>usage[b]-usage[a]);let top=[...new Set([...used,'Enfermedad o lesión común','Asuntos particulares','Exámenes','Duelo'])].slice(0,4);$('frecuentes').innerHTML=top.map(t=>`<button data-adc-tramite="${esc(t)}" aria-pressed="${selected===t}">${esc(adcTramiteLabel(t))}</button>`).join('')}
function renderTramites(){
 if(window.adcMBIT)return window.adcMBIT.render();
 const raw=$('buscar').value, code=norm(raw).replace(/[\s‐‑–—-]/g,''), dl=code==='dl01', typo=code==='bl01';
 const panel=$('adcFormSearch'), results=$('adcFormMatches');
 $('adcFormQuestion').hidden=!dl;
 $('adcFormTypo').hidden=!typo;
 if(!dl)$('adcFormMotivo').value='';
 $('adcFormTypo').onclick=()=>{$('buscar').value='DL-01';renderTramites();$('adcFormMotivo').focus()};
 results.replaceChildren();
 if(!dl&&!typo&&raw.trim()){
  for(const card of document.querySelectorAll('.adc-form-grid > *')){
   const name=card.querySelector('strong')?.textContent||'', id=card.querySelector('small')?.textContent||'';
   const djName=card.id==='tabDJ'?'Declaración jurada de cargos':card.id==='tabDJ02'?'Declaración jurada de licencias':'';
   const djMatch=djName&&(norm(djName).includes(norm(raw.trim()))||
    code==='djj'||code===('djj'+id.slice(-2)));
   if(!djMatch&&!norm(name+' '+id).includes(norm(raw.trim()))&&(!id||norm(id).replace(/[\s-]/g,'')!==code))continue;
   if(card.id==='tabL'){
    const button=document.createElement('button');button.type='button';button.className='alt';
    button.textContent='DL-01 · Licencias y permisos';
    button.onclick=()=>{$('buscar').value='DL-01';renderTramites();$('adcFormMotivo').focus()};
    results.append(button);
   }else if(card.tagName==='BUTTON'){
    const button=card.cloneNode(true);button.removeAttribute('id');if(djName)button.querySelector('strong').textContent=id+' · '+djName;results.append(button);
   }else{
    const item=document.createElement('p');item.textContent=name+' · Próximamente';results.append(item);
   }
  }
 }
 panel.hidden=!dl&&!typo&&!results.childElementCount;
 $('categoria').disabled=dl;
 const q=norm(dl?$('adcFormMotivo').value:raw), cat=dl?'':$('categoria').value;
 const found=tramites.filter(t=>!typo&&(!dl||adcDL01Ready.has(t[0]))&&(!cat||t[1]===cat)&&(!q||norm(t.join(' ')).includes(q)||q==='enfermedad comun'&&t[0]==='Enfermedad o lesión común'));
 $('contador').textContent=typo?'':found.length+' motivos encontrados';
 $('listaTramites').innerHTML=found.map(t=>`<button data-adc-tramite="${esc(t[0])}" aria-pressed="${selected===t[0]}"><span>${esc(t[3])}</span><small>${esc(t[1])}</small></button>`).join('')||(typo||results.childElementCount?'':'Sin coincidencias. Probá otra palabra.');
}
